# REPRO-058: create per-user fixtures, then apply the tutorial's distinct-user node rule.
data(world.cities,package='maps');cities<-world.cities%>%filter(country.etc=='USA',pop>=50000)%>%arrange(desc(pop))%>%slice_head(n=300);cities$location<-paste(cities$name,seq_len(nrow(cities)),sep='_');stopifnot(nrow(cities)>250)
n<-9000;fi<-sample(seq_len(nrow(cities)),n,TRUE,prob=sqrt(cities$pop));ti<-sample(seq_len(nrow(cities)),n,TRUE,prob=sqrt(cities$pop));keep<-fi!=ti;moves<-data.frame(user_id=paste0('S',sprintf('%05d',seq_len(sum(keep)))),from_loc=cities$location[fi[keep]],to_loc=cities$location[ti[keep]])
write.csv(moves,file.path(D,'repro058_user_moves_20261029.csv'),row.names=FALSE);write.csv(cities[,c('location','lat','long','name')],file.path(D,'repro058_locations_20261029.csv'),row.names=FALSE)
inc<-moves%>%group_by(to_loc)%>%summarise(n=n_distinct(user_id),.groups='drop');out<-moves%>%group_by(from_loc)%>%summarise(n=n_distinct(user_id),.groups='drop');cities$num_users<-inc$n[match(cities$location,inc$to_loc)]+out$n[match(cities$location,out$from_loc)];stopifnot(!anyNA(cities$num_users),sum(cities$num_users)==2*nrow(moves))
states<-st_read(file.path(P,'work/2026-10-29-maps-and-umap/sources/REPRO-058/data/us_shapefile/cb_2016_us_state_20m.shp'),quiet=TRUE)%>%st_make_valid()%>%st_transform(4326)
lcc<-'+proj=lcc +lat_1=33 +lat_2=45 +lat_0=39 +lon_0=-95 +datum=WGS84 +units=m +no_defs';sta<-st_transform(states,lcc);pts<-st_transform(st_as_sf(cities,coords=c('long','lat'),crs=4326,remove=FALSE),lcc);xy<-st_coordinates(pts);cities$x<-xy[,1];cities$y<-xy[,2]
off<-function(x,y,region){if(region=='AK')cbind(.25*x-1060000,.25*y-2450000)else if(region=='HI')cbind(.8*x+3730000,.8*y-1810000)else cbind(x,y)}
for(region in c('AK','HI')){i<-sta$STUSPS==region;g<-st_geometry(sta[i,]);st_geometry(sta)[i]<-if(region=='AK')g*.25+c(-1060000,-2450000)else g*.8+c(3730000,-1810000);sel<-if(region=='AK')cities$lat>50 else cities$lat<24;new<-off(cities$x[sel],cities$y[sel],region);cities$x[sel]<-new[,1];cities$y[sel]<-new[,2]}
ed<-distinct(moves,from_loc,to_loc);a<-match(ed$from_loc,cities$location);b<-match(ed$to_loc,cities$location);ed$x<-cities$x[a];ed$y<-cities$y[a];ed$xend<-cities$x[b];ed$yend<-cities$y[b];write.csv(cities,file.path(D,'repro058_nodes_20261029.csv'),row.names=FALSE);write.csv(ed,file.path(D,'repro058_edges_20261029.csv'),row.names=FALSE);st_write(sta,file.path(D,'repro058_layout_geography_20261029.gpkg'),delete_dsn=TRUE,quiet=TRUE)
p<-ggplot()+geom_sf(data=sta[!sta$STUSPS%in%c('PR','DC'),],fill='white',colour='#626269',linewidth=.15)+geom_segment(data=ed,aes(x,y,xend=xend,yend=yend),colour='#303037',alpha=.08,linewidth=.08)+geom_point(data=cities,aes(x,y,size=sqrt(num_users)),shape=21,fill='#590059',colour='white',stroke=.12,alpha=.88)+scale_size_area(max_size=4.4,breaks=sqrt(c(25,100,400)),labels=c('25','100','400'),name='Unique users\n(origin + destination)')+annotate('rect',xmin=c(-2450000,-1500000),xmax=c(-1500000,-1090000),ymin=-1950000,ymax=-1200000,fill=NA,colour='#626269',linewidth=.2)+coord_sf(crs=lcc,xlim=c(-2550000,2400000),ylim=c(-2000000,1450000),expand=FALSE,datum=NA)+th+theme(legend.position=c(.86,.10),legend.background=element_rect(fill='white',colour=NA))
finish('REPRO-058',p,'repro058_us_network_20261029','Fixed-seed synthetic per-user origin/destination records and real city positions; exact Census2016 states; same distinct-user sum rule as tutorial. Lambert conformal projection with explicit Alaska/Hawaii scale-and-shift adaptation. Not author migration data.',183,113,list(users=nrow(moves),nodes=nrow(cities),edges=nrow(ed),node_count_sum=sum(cities$num_users)))
# REPRO-080: abstract six-category geographic arrow fixture, without genetic categories or inference.
bg<-st_read(file.path(W,'BGD-adm1/gadm41_BGD_1.json'),quiet=TRUE)%>%st_make_valid();co<-data.frame(Division=c('Barisal','Chittagong','Dhaka','Khulna','Mymensingh','Rajshahi','Rangpur','Sylhet'),lon=c(90.37,91.83,90.41,89.54,90.40,88.60,89.25,91.87),lat=c(22.70,22.36,23.81,22.85,24.75,24.37,25.75,24.89))
f<-expand.grid(Group=paste('Group',LETTERS[1:6]),Destination=co$Division,stringsAsFactors=FALSE);f$Origin<-ifelse(f$Group%in%c('Group A','Group F'),'Chittagong','Dhaka');f<-f[f$Origin!=f$Destination,];f$Freq<-sample(2:40,nrow(f),TRUE);f$Month<-sample(0:15,nrow(f),TRUE);f<-f%>%group_by(Group)%>%mutate(Proportion=Freq/sum(Freq))%>%ungroup();a<-match(f$Origin,co$Division);b<-match(f$Destination,co$Division);f$x<-co$lon[a];f$y<-co$lat[a];f$xend<-co$lon[b];f$yend<-co$lat[b];f$Source<-paste('From',f$Origin);write.csv(f,file.path(D,'repro080_abstract_arrows_20261029.csv'),row.names=FALSE);write.csv(co,file.path(D,'repro080_division_labels_20261029.csv'),row.names=FALSE);stopifnot(all(abs(tapply(f$Proportion,f$Group,sum)-1)<1e-10))
co$labelX<-co$lon;co$labelY<-co$lat+.10;co$labelX[co$Division=='Mymensingh']<-90.65;co$labelX[co$Division=='Chittagong']<-91.52;co$labelY[co$Division=='Chittagong']<-21.65;co$labelX[co$Division=='Khulna']<-89.05;co$labelY[co$Division=='Dhaka']<-24.05
pal<-setNames(c('#66c2a5','#fc8d62','#8da0cb','#e78ac3','#a6d854','#ffd92f'),paste('Group',LETTERS[1:6]));p<-ggplot()+geom_sf(data=bg,fill='#ededeb',colour='#66686a',linewidth=.25)+lapply(seq_along(pal),function(i)geom_curve(data=f[f$Group==names(pal)[i],],aes(x,y,xend=xend,yend=yend,colour=Group,alpha=Month,linewidth=Proportion),curvature=seq(.10,.40,length.out=6)[i],arrow=arrow(length=unit(1.5,'mm'),type='closed')))+geom_text(data=co,aes(labelX,labelY,label=Division),family='Arial',size=2.46)+facet_wrap(~Source,nrow=1)+scale_colour_manual(values=pal)+scale_alpha_continuous(range=c(1,.22),breaks=c(0,5,10,15),name='Relative month')+scale_linewidth_continuous(range=c(.25,1.7),breaks=c(.1,.2,.3),name='Relative flow')+coord_sf(xlim=c(88,92.8),ylim=c(20.6,26.7),expand=FALSE,datum=NA)+th+theme(legend.position='bottom',legend.box='horizontal',strip.text=element_text(family='Arial',size=7),legend.key.width=unit(6,'mm'))+guides(colour=guide_legend(nrow=2),alpha=guide_legend(nrow=2),linewidth=guide_legend(nrow=2))
finish('REPRO-080',p,'repro080_bangladesh_arrows_20261029','User-authorized synthetic abstract Group A-F arrows over real GADM4.1 eight Bangladesh divisions; source-inspired Dhaka/Chittagong two-panel layout and color/width/opacity encodings only. No sequences, mutations, subpopulation identity, phylogeny or transmission reconstruction. No epidemiological claim.',183,127,list(arrows=nrow(f),groups=6,divisions=nrow(bg)))
# ASF-V14: independent positive/negative synthetic fields on a real land mask.
sf_use_s2(FALSE);world<-st_as_sf(maps::map('world',plot=FALSE,fill=TRUE));world<-st_collection_extract(st_make_valid(st_transform(world,4326)),'POLYGON');world<-st_cast(world,'MULTIPOLYGON');world<-world[!grepl('Antarctica',world$ID),];st_write(world,file.path(D,'asf14_world_geography_20261029.gpkg'),delete_dsn=TRUE,quiet=TRUE)
gr<-expand.grid(lon=seq(-179.75,179.75,.5),lat=seq(-59.75,69.75,.5));land<-lengths(st_intersects(st_as_sf(gr,coords=c('lon','lat'),crs=4326),world))>0;gr<-gr[land,]
hub<-world.cities%>%filter(pop>700000,lat<70,lat> -60);field<-rep(0,nrow(gr));for(i in seq_len(nrow(hub)))field<-field+log1p(hub$pop[i]/700000)*exp(-((gr$lon-hub$long[i])*cos(gr$lat*pi/180)/1.8)^2/2-((gr$lat-hub$lat[i])/1.5)^2/2)
gr$bright<-pmin(20,field*runif(nrow(gr),.6,1.4)*6);gr$dim<-pmin(20,field*runif(nrow(gr),.2,.8)*6);euro<-gr$lon> -12&gr$lon<30&gr$lat>45;gr$dim[euro]<-pmin(20,gr$dim[euro]*2.2);gr$bright[euro]<-gr$bright[euro]*.45;gr$bright<-ifelse(runif(nrow(gr))>.90,gr$bright,.03*gr$bright);gr$dim<-ifelse(runif(nrow(gr))>.90,gr$dim,.03*gr$dim);gr$rgb<-rgb(pmin(1,gr$bright/20+gr$dim/200),pmin(1,pmin(gr$bright,gr$dim)/20),pmin(1,gr$dim/20+gr$bright/200));write.csv(gr,file.path(D,'asf14_synthetic_bivariate_grid_20261029.csv'),row.names=FALSE)
dark<-'white';td<-theme_minimal(base_family='Arial',base_size=7)+theme(plot.background=element_rect(fill=dark,colour=NA),panel.background=element_rect(fill=dark,colour=NA),panel.grid=element_blank(),text=element_text(colour='#20252b',family='Arial',size=7),axis.text=element_text(colour='#20252b',size=7),legend.text=element_text(colour='#20252b',size=7),legend.title=element_text(colour='#20252b',size=7),axis.line=element_line(colour='#adb1b5',linewidth=.15),axis.ticks=element_line(colour='#adb1b5',linewidth=.15),plot.tag=element_text(colour='#20252b',size=8,face='bold'),plot.margin=margin(2,2,2,2),legend.background=element_rect(fill=dark,colour=NA))
wc<-st_coordinates(world);border<-data.frame(lon=wc[,1],lat=wc[,2],group=interaction(wc[,3],wc[,4],wc[,5],drop=TRUE));a<-ggplot()+geom_polygon(data=border,aes(lon,lat,group=group),fill='black',colour=NA)+geom_tile(data=gr,aes(lon,lat,fill=rgb),width=.5,height=.5)+scale_fill_identity()+coord_quickmap(xlim=c(-180,180),ylim=c(-60,70),expand=FALSE)+td+theme(axis.title=element_blank(),axis.text.x=element_blank(),axis.ticks.x=element_blank())+labs(tag='a')
