key<-expand.grid(x=seq(0,20,length.out=50),y=seq(0,20,length.out=50));key$rgb<-rgb(pmin(1,key$x/20+key$y/200),pmin(1,pmin(key$x,key$y)/20),pmin(1,key$y/20+key$x/200));k<-ggplot(key,aes(x,y,fill=rgb))+geom_raster()+scale_fill_identity()+coord_fixed()+scale_x_continuous(breaks=c(0,20))+scale_y_continuous(breaks=c(0,20))+labs(x='Brightening',y='Dimming')+td+theme(axis.text=element_text(size=7),axis.title=element_text(size=7),plot.margin=margin(1,1,1,1));a<-a+inset_element(k,left=.025,bottom=.06,right=.22,top=.40)
years<-2014:2022;pp<-list();for(y in years){j<-y-2013;v<-gr;v$lonbin<-floor(v$lon/2)*2;v$latbin<-floor(v$lat/2)*2;v$Brightening<-v$bright*(j/9)^1.2;v$Dimming<- -v$dim*(j/9)^.9;px<-aggregate(cbind(Brightening,Dimming)~lonbin,v,sum);py<-aggregate(cbind(Brightening,Dimming)~latbin,v,sum);for(type in c('Brightening','Dimming')){pp[[length(pp)+1]]<-data.frame(axis='Longitude',position=px$lonbin,value=px[[type]]/1000,year=y,type=type);pp[[length(pp)+1]]<-data.frame(axis='Latitude',position=py$latbin,value=py[[type]]/1000,year=y,type=type)}};profiles<-do.call(rbind,pp);profiles$key<-paste(profiles$type,profiles$year);write.csv(profiles,file.path(D,'asf14_synthetic_profiles_20261029.csv'),row.names=FALSE);pc<-c(setNames(colorRampPalette(c('#fff8de','#f17324','#6e2f05'))(9),paste('Brightening',years)),setNames(colorRampPalette(c('#f0fbff','#35a1da','#06356c'))(9),paste('Dimming',years)))
b<-ggplot(subset(profiles,axis=='Longitude'),aes(position,value,group=key,colour=key))+geom_line(linewidth=.24)+scale_colour_manual(values=pc)+scale_x_continuous(limits=c(-180,180),breaks=c(-150,-100,-50,0,50,100,150))+labs(x=NULL,y='Radiance change\n(MW sr-1)',tag='b')+td+theme(legend.position='none',axis.text.x=element_text(size=7));c<-ggplot(subset(profiles,axis=='Latitude'),aes(value,position,group=key,colour=key))+geom_line(linewidth=.24)+scale_colour_manual(values=pc)+scale_y_continuous(limits=c(-60,70),breaks=c(-60,-40,-20,0,20,40,60))+labs(x='Radiance change\n(MW sr-1)',y=NULL,tag='c')+td+theme(legend.position='none')
reg<-ifelse(gr$lon< -30,ifelse(gr$lat>12,'North America','South America'),ifelse(gr$lon>60,ifelse(gr$lat< -10,'Oceania','Asia'),ifelse(gr$lat>35,'Europe','Africa')));bars<-aggregate(cbind(bright,dim)~reg,gr,sum);bars$bright<-bars$bright/1000;bars$dim<-bars$dim/1000;bars<-rbind(data.frame(reg='Global',bright=sum(bars$bright),dim=sum(bars$dim)),bars);bars$baseline<-runif(nrow(bars),30,100);bl<-rbind(data.frame(region=bars$reg,type='Brightening',absolute=bars$bright,relative=100*bars$bright/bars$baseline),data.frame(region=bars$reg,type='Dimming',absolute= -bars$dim,relative= -100*bars$dim/bars$baseline));bl$region<-factor(bl$region,levels=rev(c('Global','Asia','North America','Europe','Africa','South America','Oceania')));write.csv(bl,file.path(D,'asf14_synthetic_region_summaries_20261029.csv'),row.names=FALSE)
